// =============================================================================
//  tb_rv32i_core.sv -- self-checking test of the RV32I core fixes + the
//  SRAM-based data path (byte/half accesses, load stall, vector VLD/VST polling).
//
//  Program: rv32i_test.hex  (generated by gen_rv32i_test.py)
//  Compile order: vector_accel.sv, riscv_core.sv, tb_rv32i_core.sv
//  Put rv32i_test.hex in the simulator's working directory.
// =============================================================================
`timescale 1ns/1ps

module tb_rv32i_core;
    localparam logic [31:0] END_PC = 32'h0000_01CC;   // printed by gen_rv32i_test.py

    logic clk = 0, reset = 1;
    riscv_top #(.IMEM_FILE("rv32i_test.hex")) dut (.clk(clk), .reset(reset));
    always #5 clk = ~clk;

    int errors = 0, checks = 0;

    task automatic chk_reg(input int idx, input logic [31:0] exp, input string name);
        logic [31:0] got;
        begin
            got = dut.reg_file.regs[idx]; checks++;
            if (got !== exp) begin
                errors++;
                $display("FAIL %-26s x%0d = 0x%08h, expected 0x%08h", name, idx, got, exp);
            end else $display("PASS %-26s x%0d = 0x%08h", name, idx, got);
        end
    endtask

    // data_memory now stores each 32-bit word as 4 separate byte-lane RAMs
    // (dut.data_mem.byte_lane[i].mem); reassemble the word for checking.
    function automatic logic [31:0] rd_dmem(input int word_idx);
        rd_dmem = { dut.data_mem.byte_lane[3].u_ram.mem[word_idx],
                    dut.data_mem.byte_lane[2].u_ram.mem[word_idx],
                    dut.data_mem.byte_lane[1].u_ram.mem[word_idx],
                    dut.data_mem.byte_lane[0].u_ram.mem[word_idx] };
    endfunction

    task automatic chk_mem(input int byte_addr, input logic [31:0] exp, input string name);
        logic [31:0] got;
        begin
            got = rd_dmem(byte_addr >> 2); checks++;
            if (got !== exp) begin
                errors++;
                $display("FAIL %-26s mem[0x%03h] = 0x%08h, expected 0x%08h", name, byte_addr, got, exp);
            end else $display("PASS %-26s mem[0x%03h] = 0x%08h", name, byte_addr, got);
        end
    endtask

    initial begin
        $dumpfile("tb_rv32i_core.vcd"); $dumpvars(0, tb_rv32i_core);
        repeat (3) @(posedge clk);
        @(negedge clk); reset = 0;

        begin : run
            int cyc;
            cyc = 0;
            while (dut.pc_addr !== END_PC && cyc < 5000) begin @(posedge clk); cyc++; end
            if (cyc >= 5000) begin errors++; $display("TIMEOUT pc=%h", dut.pc_addr); end
            else $display("program reached END after %0d cycles", cyc);
        end
        repeat (3) @(posedge clk); #1;

        $display("\n---- ALU / LUI / AUIPC ----");
        chk_reg(1,  32'h1234_5678, "LUI+ADDI");
        chk_reg(2,  32'h0000_0008, "AUIPC");
        chk_reg(3,  32'hFFFF_FFFF, "ADDI -1");
        chk_reg(4,  32'h1234_5679, "SUB");
        chk_reg(5,  32'hFFFF_FFFF, "SRAI");
        chk_reg(6,  32'h0FFF_FFFF, "SRLI");
        chk_reg(7,  32'h2345_6780, "SLLI");
        chk_reg(19, 32'h0000_0002, "XOR");
        chk_reg(29, 32'h0000_0001, "SLT (signed)");

        $display("\n---- byte / half / word memory ----");
        chk_reg(9,  32'h0000_0078, "LB  byte0");
        chk_reg(10, 32'h0000_0056, "LB  byte1");
        chk_reg(11, 32'hFFFF_FFFF, "LB  sign-extend");
        chk_reg(12, 32'h0000_00FF, "LBU zero-extend");
        chk_reg(13, 32'hFFFF_FF34, "LH  sign-extend");
        chk_reg(14, 32'h0000_FF34, "LHU zero-extend");
        chk_reg(15, 32'hFF34_FFFF, "SB/SH then LW");
        chk_mem(32'h40, 32'hFF34_FFFF, "SB/SH byte enables");

        $display("\n---- branches (all six) ----");
        chk_reg(20, 32'd32, "skipped adds not executed");
        chk_reg(21, 32'd1,  "BLTU not taken");

        $display("\n---- JAL / JALR ----");
        chk_reg(22, 32'h0000_00A0, "JAL link");
        chk_reg(23, 32'd0,         "JAL skipped instr");
        chk_reg(24, 32'h0000_00B4, "JALR target");
        chk_reg(25, 32'h0000_00B0, "JALR link");
        chk_reg(26, 32'd0,         "JALR skipped instr");
        chk_reg(27, 32'd1,         "JALR landed");

        $display("\n---- vector accelerator through the CPU ----");
        chk_reg(28, 32'h4000_0000, "accelerator base (LUI)");
        chk_mem(32'h100, 8,   "VADD lane0 via lw/sw");
        chk_mem(32'h104, 2,   "VADD lane1");
        chk_mem(32'h108, 8,   "VADD lane2");
        chk_mem(32'h10C, 14,  "VADD lane3");
        chk_mem(32'h110, 16,  "VRSUM");
        chk_mem(32'h114, 20,  "VDOT");
        chk_mem(32'h0A0, 8,   "VST lane0 -> SRAM");
        chk_mem(32'h0A4, 2,   "VST lane1");
        chk_mem(32'h0A8, 8,   "VST lane2");
        chk_mem(32'h0AC, 14,  "VST lane3");
        chk_mem(32'h118, 110, "VLD V3 then VRSUM");
        chk_mem(32'h11C, 6,   "command counter");
        chk_mem(32'h120, 2,   "illegal op -> ERR");

        if (errors == 0) $display("\nALL TESTS PASSED (%0d checks)", checks);
        else             $display("\n%0d OF %0d CHECKS FAILED", errors, checks);
        $finish;
    end
endmodule